// ───────────────────────────────────────────────────────────
// LLM Error Handler
// ───────────────────────────────────────────────────────────
let buildData = {};
try { buildData = $('Build Prompt').first().json; } catch (e) {}
const url = buildData.url || $json.url || '';
const language = buildData.language || $json.language || 'en';
const slack_channel = buildData.slack_channel || $json.slack_channel || '';
const slack_ts = buildData.slack_ts || $json.slack_ts || '';
const slack_thread_ts = buildData.slack_thread_ts || $json.slack_thread_ts || null;
const errMsg = $json.error?.message || $json.error || $json.message || $json.errorMessage || 'Both Local LLM and OpenRouter fallback failed';
return [{ json: { error: `LLM failure: ${errMsg}`, url, language, slack_channel, slack_ts, slack_thread_ts } }];

const body = $json.body || $json;
const event = body.event || {};
const headers = $json.headers || {};

if (headers['x-slack-retry-num']) return [];

const BOT_USER_ID = 'U07K8QJ9XYZ';

if (event.subtype === 'message_changed') {
  const prev = event.previous_message?.text || '';
  const curr = event.message?.text || '';
  if (prev === curr) return [];
  const extractUrls = (text) => {
    const urls = new Set();
    const slackRx = /<(https?:\/\/[^>|]+)(\|[^>]+)?>/g;
    let m;
    while ((m = slackRx.exec(text)) !== null) urls.add(m[1]);
    const plainRx = /https?:\/\/[^\s<>"'\[\]{}|]+/g;
    while ((m = plainRx.exec(text)) !== null) urls.add(m[0].replace(/[.,;:)]+$/, ''));
    return urls;
  };
  const prevUrls = extractUrls(prev);
  const currUrls = extractUrls(curr);
  const newUrls = [...currUrls].map(u => u.split('|')[0]).filter(u => !prevUrls.has(u) && u.match(/^https?:\/\/.+\..+/));
  if (newUrls.length === 0) return [];
  const user = event.message?.user || event.previous_message?.user || '';
  if (!user || user === BOT_USER_ID || event.message?.bot_id) return [];
  const staticData = $getWorkflowStaticData('global');
  if (!staticData.processedUrls) staticData.processedUrls = {};
  if (!staticData.processedMsgs) staticData.processedMsgs = {};
  const msgKey = `${user}_${event.message?.ts || event.ts}_edited`;
  if (staticData.processedMsgs[msgKey]) return [];
  staticData.processedMsgs[msgKey] = Date.now();
  const twoDaysAgo = Date.now() - 172800000;
  for (const k of Object.keys(staticData.processedUrls)) if (staticData.processedUrls[k] < twoDaysAgo) delete staticData.processedUrls[k];
  for (const k of Object.keys(staticData.processedMsgs)) if (staticData.processedMsgs[k] < twoDaysAgo) delete staticData.processedMsgs[k];
  const results = [];
  const fourHoursAgo = Date.now() - 14400000;
  for (const url of newUrls) {
    const isDuplicate = staticData.processedUrls[url] > fourHoursAgo;
    if (!isDuplicate) staticData.processedUrls[url] = Date.now();
    const slack_ts = event.message?.ts || event.ts;
    const slack_thread_ts = event.message?.thread_ts || null;
    results.push({ json: { isDuplicate, url, slack_channel: event.channel, slack_user: user, slack_ts, slack_thread_ts } });
  }
  return results;
}

const skipSubtypes = ['bot_message','message_deleted','channel_join','channel_leave','channel_topic','channel_purpose','file_share','pinned_item','unpinned_item'];
if (event.subtype && skipSubtypes.includes(event.subtype)) return [];
if (event.type !== 'message' || event.bot_id || event.user === BOT_USER_ID || !event.text) return [];
const text = event.text || '';
const urls = new Set();
const slackRx = /<(https?:\/\/[^>|]+)(\|[^>]+)?>/g;
let m;
while ((m = slackRx.exec(text)) !== null) urls.add(m[1]);
const plainRx = /https?:\/\/[^\s<>"'\[\]{}|]+/g;
while ((m = plainRx.exec(text)) !== null) urls.add(m[0].replace(/[.,;:)]+$/, ''));
const validUrls = [...urls].map(u => u.split('|')[0]).filter(u => u.match(/^https?:\/\/.+\..+/));
if (validUrls.length === 0) return [];
const staticData = $getWorkflowStaticData('global');
if (!staticData.processedUrls) staticData.processedUrls = {};
if (!staticData.processedMsgs) staticData.processedMsgs = {};
const msgKey = `${event.user}_${event.ts}`;
if (staticData.processedMsgs[msgKey]) return [];
staticData.processedMsgs[msgKey] = Date.now();
const fourHoursAgo = Date.now() - 14400000;
const twoDaysAgo = Date.now() - 172800000;
for (const k of Object.keys(staticData.processedUrls)) if (staticData.processedUrls[k] < twoDaysAgo) delete staticData.processedUrls[k];
for (const k of Object.keys(staticData.processedMsgs)) if (staticData.processedMsgs[k] < twoDaysAgo) delete staticData.processedMsgs[k];
const results = [];
for (const url of validUrls) {
  const isDuplicate = staticData.processedUrls[url] > fourHoursAgo;
  if (!isDuplicate) staticData.processedUrls[url] = Date.now();
  const slack_ts = event.ts;
  const slack_thread_ts = event.thread_ts || null;
  results.push({ json: { isDuplicate, url, slack_channel: event.channel, slack_user: event.user, slack_ts, slack_thread_ts } });
}
return results;

// ───────────────────────────────────────────────────────────
// Extract Text (multi-strategy, length-aware)
// ───────────────────────────────────────────────────────────
const headers = $json.headers || {};
const contentType = (headers['content-type'] || headers['Content-Type'] || '').toLowerCase();
let ctx = {};
try { ctx = $('Is Duplicate?').first().json || {}; } catch (e) {}
const url = $json.url || ctx.url || '';
const slack_channel = $json.slack_channel || ctx.slack_channel || '';
const slack_ts = $json.slack_ts || ctx.slack_ts || '';
const slack_thread_ts = $json.slack_thread_ts || ctx.slack_thread_ts || null;

const MIN_OK = 200;
const MIN_GOOD = 1500;
const MAX_LEN = 12000;

const decodeEntities = (str) => str
  .replace(/&quot;/g, '"').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/&#39;/g, "'").replace(/&apos;/g, "'").replace(/&#x27;/g, "'")
  .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(Number(n)));

if ($json.needsJina) {
  return [{ json: { needsJina: true, url, slack_channel, slack_ts, slack_thread_ts, error: $json.error || 'Direct fetch blocked' } }];
}
if (contentType && !contentType.includes('text/html') && !contentType.includes('application/xhtml') && !contentType.includes('text/plain')) {
  return [{ json: { error: `Non-HTML content (${contentType.split(';')[0]}). Cannot extract article text.`, url, slack_channel, slack_ts, slack_thread_ts, needsJina: false } }];
}
const rawHtml = $json.body || $json.data || $json.html || $json.content || '';
const html = typeof rawHtml === 'string' ? rawHtml : '';
if (!html || html.length < 100) {
  return [{ json: { error: 'No HTML content received', url, slack_channel, slack_ts, slack_thread_ts, needsJina: true } }];
}

const stripNoise = (h) => h
  .replace(/<figcaption[\s\S]*?<\/figcaption>/gi, '')
  .replace(/<figure[\s\S]*?<\/figure>/gi, '')
  .replace(/<div[^>]*class="[^"]*(?:caption|credit|photo-credit|image-credit|img-credit|media-credit|photographer|תמונה|צילום)[^"]*"[^>]*>[\s\S]*?<\/div>/gi, '')
  .replace(/<span[^>]*class="[^"]*(?:caption|credit|photo-credit|image-credit|photographer|תמונה|צילום)[^"]*"[^>]*>[\s\S]*?<\/span>/gi, '')
  .replace(/<p[^>]*class="[^"]*(?:caption|credit|photo-credit|image-credit|photographer|צילום)[^"]*"[^>]*>[\s\S]*?<\/p>/gi, '')
  .replace(/<script[\s\S]*?<\/script>/gi, '')
  .replace(/<style[\s\S]*?<\/style>/gi, '')
  .replace(/<nav[\s\S]*?<\/nav>/gi, '')
  .replace(/<aside[\s\S]*?<\/aside>/gi, '')
  .replace(/<footer[\s\S]*?<\/footer>/gi, '');

const toText = (h) => stripNoise(h)
  .replace(/<br\s*\/?>/gi, ' ')
  .replace(/<\/(?:p|div|li|h[1-6]|blockquote)>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

const stripCaptionText = (t) => t
  .replace(/צילום[י]?\s*[:\/|]?\s*[^.;\n]{0,120}סעיף\s*\d+[א-ת]?'?/g, '')
  .replace(/\(\s*צילום[י]?\s*[:\/|][^)]{0,80}\)/g, '')
  .replace(/(?:תמונת?\s*(?:ארכיון|אילוסטרציה)|צילום\s*אילוסטרציה)[^.;\n]{0,60}/g, '')
  .replace(/(?:photo|image|illustration)\s*(?:credit|by|courtesy|via)\s*[:.]?\s*[^.;\n]{0,100}/gi, '')
  .replace(/(?:^|\n)\s*(?:credit|source|photo)\s*:\s*[^\n]{0,100}/gi, '');

const balancedDiv = (src, startIdx) => {
  const re = /<(\/?)div\b[^>]*>/gi;
  re.lastIndex = startIdx;
  let depth = 0, m;
  while ((m = re.exec(src)) !== null) {
    if (m[1] === '') depth++;
    else { depth--; if (depth === 0) return src.slice(startIdx, re.lastIndex); }
  }
  return src.slice(startIdx);
};
const longestOf = (arr) => arr.reduce((a, b) => (b.length > a.length ? b : a), '');

const metaContent = (names) => {
  for (const n of names) {
    const key = n.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const a = html.match(new RegExp(`<meta[^>]+(?:name|property)=["']${key}["'][^>]*?content=["']([^"']*)["']`, 'i'));
    const b = html.match(new RegExp(`<meta[^>]+content=["']([^"']*)["'][^>]*?(?:name|property)=["']${key}["']`, 'i'));
    const v = ((a && a[1]) || (b && b[1]) || '').trim();
    if (v) return decodeEntities(v);
  }
  return '';
};
const ldMeta = () => {
  const out = { author: '', published: '', headline: '' };
  const authorName = (a) => { if (!a) return ''; if (typeof a === 'string') return a; if (Array.isArray(a)) return a.map(authorName).filter(Boolean).join(', '); return a.name || ''; };
  const visit = (o) => { if (!o) return; if (Array.isArray(o)) { o.forEach(visit); return; } if (typeof o === 'object') { if (!out.author && o.author) out.author = authorName(o.author); if (!out.published && o.datePublished) out.published = String(o.datePublished); if (!out.headline && o.headline) out.headline = String(o.headline); if (o['@graph']) visit(o['@graph']); } };
  const rx = /<script[^>]*type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi;
  let m;
  while ((m = rx.exec(html)) !== null) { try { visit(JSON.parse(m[1])); } catch (e) {} }
  return out;
};
const anchorAuthor = () => {
  const m = html.match(/<a[^>]+href=["'][^"']*(?:\/writer\/|\/author\/|\/authors\/|\/byline\/|\/reporter\/|\/journalist\/)[^"']*["'][^>]*>([\s\S]*?)<\/a>/i) || html.match(/<a[^>]+rel=["']author["'][^>]*>([\s\S]*?)<\/a>/i);
  const t = m ? toText(m[1]) : '';
  return t.length >= 2 && t.length <= 60 ? t : '';
};
const ld = ldMeta();
const authorTag = metaContent(['author', 'article:author', 'vr:author', 'og:article:author', 'parsely-author', 'dc.creator', 'sailthru.author', 'twitter:creator']);
const meta = {
  title: metaContent(['og:title', 'twitter:title']) || ld.headline || ((html.match(/<title[^>]*>([\s\S]*?)<\/title>/i) || [])[1] || ''),
  author: anchorAuthor() || (/^https?:/i.test(authorTag) ? '' : authorTag) || ld.author,
  published: metaContent(['article:published_time', 'og:published_time', 'vr:published_time', 'datePublished', 'date']) || ld.published || ((html.match(/<time[^>]+datetime=["']([^"']+)["']/i) || [])[1] || ''),
  site: metaContent(['og:site_name']),
  description: metaContent(['og:description', 'description', 'twitter:description'])
};
for (const k of Object.keys(meta)) meta[k] = decodeEntities(String(meta[k] || '')).replace(/\s+/g, ' ').trim().slice(0, 400);

const getLd = () => { let best = ''; const visit = (o) => { if (!o) return; if (Array.isArray(o)) { o.forEach(visit); return; } if (typeof o === 'object') { if (typeof o.articleBody === 'string' && o.articleBody.length > best.length) best = o.articleBody; if (o['@graph']) visit(o['@graph']); } }; const rx = /<script[^>]*type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi; let m; while ((m = rx.exec(html)) !== null) { try { visit(JSON.parse(m[1])); } catch (e) {} } return best.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim(); };
const getBodyDiv = () => { const rx = /<div[^>]*class="[^"]*(?:art_body|article_text|article-body|article__body|post-content|entry-content|story-body|article__content|content-body)[^"]*"[^>]*>/gi; const found = []; let m; while ((m = rx.exec(html)) !== null) found.push(toText(balancedDiv(html, m.index))); return longestOf(found); };
const getParas = () => { const seen = new Set(); const out = []; const push = (raw) => { const t = toText(raw); if (t.length > 40 && !/cookie|privacy|subscribe|newsletter|הרשמה|פרטיות/i.test(t) && !seen.has(t)) { seen.add(t); out.push(t); } }; for (const m of html.matchAll(/<p(?:\s[^>]*)?>([\s\S]*?)<\/p>/gi)) { if (!/class="[^"]*(?:caption|credit|photo|צילום)/i.test(m[0].slice(0, 200))) push(m[1]); } for (const m of html.matchAll(/<div[^>]*class="[^"]*text_editor_paragraph[^"]*"[^>]*>([\s\S]*?)<\/div>/gi)) push(m[1]); return out.length >= 3 ? out.join(' ') : ''; };
const getArticle = () => longestOf([...html.matchAll(/<article[^>]*>([\s\S]*?)<\/article>/gi)].map(m => toText(m[1])));
const getMain = () => longestOf([...html.matchAll(/<main[^>]*>([\s\S]*?)<\/main>/gi)].map(m => toText(m[1])));

const strategies = [['ldjson', getLd], ['bodyDiv', getBodyDiv], ['paragraphs', getParas], ['article', getArticle], ['main', getMain]];
let text = '', used = '';
let longest = '', longestName = '';
for (const [name, fn] of strategies) { let t = ''; try { t = fn() || ''; } catch (e) {} if (t.length > longest.length) { longest = t; longestName = name; } if (t.length >= MIN_GOOD) { text = t; used = name; break; } }
if (!text) { text = longest; used = longestName; }

text = text.replace(/all rights reserved|כל הזכויות שמורות|copyright \d{4}|©\s*\d{4}/gi, '').replace(/follow us on.*|עקבו אחרינו.*/gi, '');
text = stripCaptionText(text).replace(/\s+/g, ' ').trim();
text = decodeEntities(text);

if (!text || text.length < MIN_OK) return [{ json: { error: 'Direct extraction failed', meta, url, slack_channel, slack_ts, slack_thread_ts, needsJina: true } }];
if (text.length < MIN_GOOD) return [{ json: { needsJina: true, error: `Direct extraction thin (${text.length} chars via ${used})`, directArticle: text, meta, url, slack_channel, slack_ts, slack_thread_ts } }];
if (text.length > MAX_LEN) text = text.substring(0, MAX_LEN) + '... [truncated]';
return [{ json: { article: text, url, charCount: text.length, extractMethod: used, meta, needsJina: false, slack_channel, slack_ts, slack_thread_ts } }];

const url = $('Is Duplicate?').first().json.url || '';
const slack_channel = $('Is Duplicate?').first().json.slack_channel || '';
const slack_ts = $('Is Duplicate?').first().json.slack_ts || '';
const slack_thread_ts = $('Is Duplicate?').first().json.slack_thread_ts || null;
const errMsg = $json.error?.message || $json.message || 'Network/fetch error';
return [{ json: { needsJina: true, url, slack_channel, slack_ts, slack_thread_ts, error: `Fetch failed: ${errMsg}` } }];

const url = $('Is Duplicate?').first().json.url || '';
const slack_channel = $('Is Duplicate?').first().json.slack_channel || '';
const slack_ts = $('Is Duplicate?').first().json.slack_ts || '';
const slack_thread_ts = $('Is Duplicate?').first().json.slack_thread_ts || null;
if ($json.error) return [{ json: { needsJina: true, url, slack_channel, slack_ts, slack_thread_ts, error: `Fetch error: ${$json.error}` } }];
const status = $json.statusCode || 200;
const JINA_STATUSES = [401, 403, 404, 429, 451, 500, 502, 503, 504];
if (JINA_STATUSES.includes(status)) return [{ json: { needsJina: true, url, slack_channel, slack_ts, slack_thread_ts, error: `HTTP ${status} — direct fetch blocked` } }];
return [{ json: { ...$json, url, slack_channel, slack_ts, slack_thread_ts } }];

const url = $json.url || '';
const text = $json.text || '';
const isError = text.startsWith('⚠️');
let domain = '';
try { domain = new URL(url).hostname.replace(/^www\./, ''); } catch (e) {}
const record = { type: 'summary', ts: new Date().toISOString(), url, domain, title: $json.title || '', language: $json.language || '', char_count: $json.charCount || 0, extract_method: $json.extractMethod || '', bullet_count: $json.bulletCount ?? null, status: isError ? 'error' : 'success', slack_channel: $json.slack_channel || '', error_message: isError ? text : null };
return [{ json: { ...record, logKey: 'log:' + record.ts.slice(0, 7), logJson: JSON.stringify(record) } }];

const err = $json.error || 'Unknown error';
const url = $json.url || '';
const language = $json.language || 'en';
const slack_channel = $json.slack_channel || '';
const slack_ts = $json.slack_ts || '';
const slack_thread_ts = $json.slack_thread_ts || null;
const msgs = { he: '⚠️ נכשל בסיכום המאמר', ru: '⚠️ Не удалось обобщить статью', en: '⚠️ Failed to summarize article' };
const reasons = { he: 'סיבה:', ru: 'Причина:', en: 'Reason:' };
return [{ json: { text: `${msgs[language] || msgs.en}\n${reasons[language] || reasons.en} ${err}`, url, language, charCount: 0, slack_channel, slack_ts, slack_thread_ts } }];

const raw = $json.data || $json.body || $json.content || '';
const prevData = $('Needs Jina Fallback?').first().json;
const url = prevData.url || '';
const slack_channel = prevData.slack_channel || '';
const slack_ts = prevData.slack_ts || '';
const slack_thread_ts = prevData.slack_thread_ts || null;
const directArticle = prevData.directArticle || '';
const MAX_LEN = 12000;
let text = typeof raw === 'string' ? raw : (raw ? JSON.stringify(raw) : '');
const jTitle = (text.match(/^Title:\s*(.+)$/im) || [])[1] || '';
const jPub = (text.match(/^Published Time:\s*(.+)$/im) || [])[1] || '';
const pm = prevData.meta || {};
const meta = { title: pm.title || jTitle.trim(), author: pm.author || '', published: pm.published || jPub.trim(), site: pm.site || '', description: pm.description || '' };
text = text.replace(/^(?:Title|URL Source|Published Time):.*$/gim, '').replace(/^Markdown Content:\s*$/im, '');
text = text.replace(/!\[.*?\]\(.*?\)/g, '').replace(/\[([^\]]+)\]\(.*?\)/g, '$1').replace(/#{1,6}\s*/g, '').replace(/[*_]{1,3}/g, '').replace(/\s+/g, ' ').trim();
text = text.replace(/all rights reserved|כל הזכויות שמורות|copyright \d{4}|©\s*\d{4}/gi, '').replace(/follow us on.*|עקבו אחרינו.*/gi, '').replace(/\s+/g, ' ').trim();
text = text.replace(/צילום[י]?\s*[:\/|]?\s*[^.;\n]{0,120}סעיף\s*\d+[א-ת]?'?/g, '').replace(/\(\s*צילום[י]?\s*[:\/|][^)]{0,80}\)/g, '').replace(/(?:תמונת?\s*(?:ארכיון|אילוסטרציה)|צילום\s*אילוסטרציה)[^.;\n]{0,60}/g, '').replace(/(?:photo|image|illustration)\s*(?:credit|by|courtesy|via)\s*[:.]?\s*[^.;\n]{0,100}/gi, '').replace(/(?:^|\n)\s*(?:credit|source|photo)\s*:\s*[^\n]{0,100}/gi, '').replace(/\s+/g, ' ').trim();
let extractMethod = 'jina';
if (directArticle.length > text.length) { text = directArticle; extractMethod = 'direct-thin'; }
if (!text || text.length < 200) { let reason = prevData.error || 'Could not extract article text.'; if (String(reason).startsWith('Direct extraction')) reason += ' Jina Reader also failed — site may require login or block automated access.'; return [{ json: { error: reason, meta, url, slack_channel, slack_ts, slack_thread_ts, needsJina: false } }]; }
if (text.length > MAX_LEN) text = text.substring(0, MAX_LEN) + '... [truncated]';
return [{ json: { article: text, url, charCount: text.length, extractMethod, meta, needsJina: false, slack_channel, slack_ts, slack_thread_ts } }];

if (($json.text || '').startsWith('⚠️')) return [];
let dl = {};
try { dl = $('Detect Language').first().json || {}; } catch (e) { return []; }
if (!dl.article || !dl.slack_channel) return [];
const root = dl.slack_thread_ts || dl.slack_ts;
if (!root) return [];
const art = { url: dl.url || '', title: $json.title || (dl.meta && dl.meta.title) || '', article: dl.article, summary: $json.text || '', language: dl.language || 'en', meta: dl.meta || {}, created: Date.now() };
return [{ json: { threadKey: `thread:${dl.slack_channel}:${root}`, threadValue: JSON.stringify({ art: JSON.stringify(art), quiz: 'null', hist: '[]' }) } }];

let mark = {};
try { mark = $('Mark URL Processed').first().json || {}; } catch (e) {}
if ((mark.text || '').startsWith('⚠️')) return [];
const ts = $json.ts || $json.message_timestamp || ($json.message && $json.message.ts);
const channel = mark.slack_channel || $json.channel;
const root = mark.slack_thread_ts || mark.slack_ts;
if (!ts || !channel || !root) return [];
return [{ json: { mapKey: `msg:${channel}:${ts}`, mapValue: String(root) } }];

let mark = {};
try { mark = $('Mark URL Processed').first().json || {}; } catch (e) {}
if ((mark.text || '').startsWith('⚠️')) return [];
const ts = $json.ts || $json.message_timestamp || ($json.message && $json.message.ts);
const channel = mark.slack_channel || $json.channel;
if (!ts || !channel) return [];
const names = ['brain', 'zap', mark.language === 'he' ? 'flag-us' : 'flag-il', 'pushpin'];
return names.map(name => ({ json: { channel, ts, name } }));

const now = new Date();
const key = (d) => 'log:' + d.toISOString().slice(0, 7);
const prev = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth() - 1, 1));
return [{ json: { k1: key(now), k2: key(prev), now: now.toISOString() } }];

const DIGEST_CHANNEL_ID = 'C09BFKKCMQ8';
const DIGEST_LANGUAGE = 'he';
const DAYS = 7;
const MAX_ITEMS = 15;
const RLM = '\u200F', LRM = '\u200E';
const wrapLatin = (t) => t.replace(/[A-Za-z0-9]+(?:[.,:\/\-][A-Za-z0-9]+)*/g, (tok) => (/[A-Za-z]/.test(tok) || /[.,:\/\-]/.test(tok)) ? `${LRM}${tok}${LRM}` : tok);
const esc = (t) => String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const lang = ['he', 'ru', 'en'].includes(DIGEST_LANGUAGE) ? DIGEST_LANGUAGE : 'en';
const parseList = (arr) => (Array.isArray(arr) ? arr : []).map((s) => { try { return JSON.parse(s); } catch (e) { return null; } }).filter(Boolean);
