const RLM = '\u200F', LRM = '\u200E';
const wrapLatin = (t) => t.replace(/[A-Za-z0-9]+(?:[.,:\/\-][A-Za-z0-9]+)*/g, (tok) => (/[A-Za-z]/.test(tok) || /[.,:\/\-]/.test(tok)) ? `${LRM}${tok}${LRM}` : tok);
const wrapOutsideUrls = (t) => t.split(/(https?:\/\/[^\s)>\]]+)/g).map((seg, i) => (i % 2 ? seg : wrapLatin(seg))).join('');
const esc = (t) => String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const toSlack = (raw, lang) => { let t = raw; if (lang === 'he') t = wrapOutsideUrls(t); t = esc(t).replace(/\[([^\]]+)\]\((https?:\/\/[^)\s]+)\)/g, '<$2|$1>').replace(/\*\*(.+?)\*\*/g, '*$1*').replace(/^#{1,6}\s*(.+)$/gm, '*$1*').replace(/^\s*[-*]\s+/gm, '• '); if (t.length > 3500) t = t.slice(0, 3500).trimEnd() + '…'; if (lang === 'he') t = t.split('\n').map(l => (l.trim() ? RLM + l : l)).join('\n'); return t; };
const prevHistory = Array.isArray(q.history) ? q.history : [];
if (!raw) { const empty = { he:'⚠️ לא התקבלה תשובה.', ru:'⚠️ Ответ не получен.', en:'⚠️ No answer was generated.' }; const tvFields = { hist: JSON.stringify(prevHistory) }; if (q.updatedQuizJson) tvFields.quiz = q.updatedQuizJson; return [{ json: { text: empty[q.qLang]||empty.en, slack_channel: q.slack_channel, slack_thread_ts: q.slack_thread_ts, threadKey: q.threadKey, threadValue: JSON.stringify(tvFields) } }]; }
const hist = prevHistory.concat([{ q: String(q.question||'').slice(0,500), a: raw.slice(0,1200) }]).slice(-6);
const tvFields = { hist: JSON.stringify(hist) };
if (q.updatedQuizJson) tvFields.quiz = q.updatedQuizJson;
const cancelLine = q.cancelNotice ? ((q.qLang==='he'?RLM:'') + esc(q.qLang==='he'?wrapOutsideUrls(q.cancelNotice):q.cancelNotice) + '\n\n') : '';
return [{ json: { text: cancelLine + toSlack(raw, q.qLang), slack_channel: q.slack_channel, slack_thread_ts: q.slack_thread_ts, threadKey: q.threadKey, threadValue: JSON.stringify(tvFields) } }];

// ── Validate & Format1 — v2: fixes quotes inside bullets + fixed footer ──
let raw = $json.output || $json.text || $json.content || '';
if (typeof raw !== 'string') raw = JSON.stringify(raw);
const bp = $('Build Prompt').first().json;
const url = bp.url || '';
const language = bp.language || 'en';
const slack_channel = bp.slack_channel || '';
const slack_ts = bp.slack_ts || '';
const slack_thread_ts = bp.slack_thread_ts || null;
const charCount = bp.charCount || 0;
const extractMethod = bp.extractMethod || '';

const decodeEntities = (str) => str
  .replace(/&quot;/g, '"').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/&#39;/g, "'").replace(/&apos;/g, "'").replace(/&#x27;/g, "'")
  .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(Number(n)));

try { const unwrapped = JSON.parse(raw); if (typeof unwrapped === 'string') raw = unwrapped; } catch (e) {}

raw = raw.replace(/<think>[\s\S]*?<\/think>/gi, '').trim();
let s = raw.replace(/```json\s*/gi, '').replace(/```\s*/g, '');

// ── FIX 1: protect curly double quotes. They are CONTENT (e.g. “diary.”), never JSON syntax.
// The old code converted them to straight quotes, which broke the JSON.
const OQ = '\uE000', CQ = '\uE001';
s = s.replace(/\u201C/g, OQ).replace(/\u201D/g, CQ);
const restoreQuotes = (t) => String(t).split(OQ).join('\u201C').split(CQ).join('\u201D');

// Hebrew acronym quotes (צה"ל etc.) -> escaped
s = s.replace(/([\u0590-\u05FF])["״\uE000\uE001]([\u0590-\u05FF])/g, '$1\\"$2');

// Merge duplicate bullets keys
if ((s.match(/"bullets"\s*:/g) || []).length > 1) {
  const tm = s.match(/"title"\s*:\s*"((?:[^"\\]|\\.)*)"/);
  const allBullets = [];
  const bulletRx = /"bullets"\s*:\s*\[\s*"((?:[^"\\]|\\.)*)"\s*\]/g;
  let bm;
  while ((bm = bulletRx.exec(s)) !== null) allBullets.push(bm[1]);
  if (tm && allBullets.length > 1) s = JSON.stringify({ title: tm[1], bullets: allBullets });
}

const si = s.indexOf('{');
const ei = s.lastIndexOf('}');
if (si > -1 && ei > si) s = s.substring(si, ei + 1);

s = s.replace(/[\r\n]+/g, ' ').replace(/[\u2018\u2019]/g, "'").trim();

// ── FIX 2: escape straight quotes that sit INSIDE a string value.
// A quote is a real string end only if what follows is a JSON delimiter.
const fixInternalQuotes = (str) => {
  let out = '';
  let inStr = false, escaped = false;
  for (let i = 0; i < str.length; i++) {
    const ch = str[i];
    if (escaped) { out += ch; escaped = false; continue; }
    if (ch === '\\') { out += ch; escaped = true; continue; }
    if (ch !== '"') { out += ch; continue; }
    if (!inStr) { inStr = true; out += ch; continue; }
    const rest = str.slice(i + 1).trimStart();
    let isEnd = false;
    if (rest === '' || rest[0] === ']' || rest[0] === '}' || rest[0] === ':') isEnd = true;
    else if (rest[0] === ',') {
      const afterComma = rest.slice(1).trimStart();
      isEnd = afterComma === '' || afterComma[0] === '"' || afterComma[0] === ']' || afterComma[0] === '}';
    }
    if (isEnd) { inStr = false; out += ch; } else { out += '\\"'; }
  }
  return out;
};
s = fixInternalQuotes(s);

let title = 'Summary';
let bullets = [];

try {
  const obj = JSON.parse(s);
  title = obj.title || 'Summary';
  bullets = Array.isArray(obj.bullets) ? obj.bullets : [];
} catch (e) {
  try {
    let fixed = s.replace(/,\s*]/g, ']').replace(/,\s*}/g, '}');
    const obj = JSON.parse(fixed);
    title = obj.title || 'Summary';
    bullets = Array.isArray(obj.bullets) ? obj.bullets : [];
  } catch (e2) {
    try {
      let repair = s;
      const openBrackets = (repair.match(/\[/g) || []).length;
      const closeBrackets = (repair.match(/\]/g) || []).length;
      const openBraces = (repair.match(/\{/g) || []).length;
      const closeBraces = (repair.match(/\}/g) || []).length;
      const quotes = repair.match(/(?<!\\)"/g) || [];
      if (quotes.length % 2 !== 0) repair += '"';
      for (let i = 0; i < (openBrackets - closeBrackets); i++) repair += ']';
      for (let i = 0; i < (openBraces - closeBraces); i++) repair += '}';
      repair = repair.replace(/,\s*]/g, ']').replace(/,\s*}/g, '}');
      const obj = JSON.parse(repair);
      title = obj.title || 'Summary';
      bullets = Array.isArray(obj.bullets) ? obj.bullets : [];
    } catch (e3) {
      try {
        const tm = s.match(/"title"\s*:\s*"((?:[^"\\]|\\.)*)"/);
        if (tm) title = tm[1].replace(/\\"/g, '"').replace(/\\n/g, ' ');
        const bulletsStart = s.indexOf('"bullets"');
        if (bulletsStart > -1) {
          const afterBullets = s.substring(bulletsStart);
          const bracketStart = afterBullets.indexOf('[');
          if (bracketStart > -1) {
            const bulletsContent = afterBullets.substring(bracketStart + 1);
            const completeStrings = [];
            let inString = false;
            let current = '';
            let escaped = false;
            for (let i = 0; i < bulletsContent.length; i++) {
              const ch = bulletsContent[i];
              if (escaped) { current += ch; escaped = false; continue; }
              if (ch === '\\') { current += ch; escaped = true; continue; }
              if (ch === '"') {
                if (inString) {
                  if (current.length > 25) completeStrings.push(current.replace(/\\"/g, '"').replace(/\\n/g, ' '));
                  current = ''; inString = false;
                } else {
                  inString = false; current = ''; inString = true;
                }
              } else if (inString) current += ch;
            }
            if (completeStrings.length > 0) bullets = completeStrings;
          }
        }
      } catch (e4) {
        const tm = s.match(/"title"\s*:\s*"((?:[^"\\]|\\.)*)"/);
        const bm = s.match(/"bullets"\s*:\s*\[([\s\S]*?)\]/);
        if (tm) title = tm[1];
        if (bm) bullets = [...bm[1].matchAll(/"((?:[^"\\]|\\.){10,})"/g)].map(m => m[1]).filter(b => b.length > 15);
      }
    }
  }
}

title = restoreQuotes(decodeEntities(String(title)));

bullets = bullets
  .map(b => {
    let cleaned = String(b)
      .replace(/^[•\-\s]+/, '')
      .replace(/\s*•\s*/g, ' ')
      .replace(/\.{2,}/g, '.')
      .replace(/\s+/g, ' ')
      .replace(/\\n/g, ' ')
      .replace(/\\"/g, '"')
      .trim();
    return restoreQuotes(decodeEntities(cleaned));
  })
  .filter(b => {
    if (!b || b.length < 25) return false;
    const lc = b.toLowerCase();
    return !lc.includes('no further details') && !lc.includes('no additional details') &&
           !lc.includes('לא נמצאו פרטים') && !lc.includes('אין פרטים') &&
           !lc.includes('информация недоступна');
  });

if (bullets.length === 0) {
  const noContent = { he: 'לא הצלחתי לחלץ מידע מהמאמר', ru: 'Не удалось извлечь информацию', en: 'Could not extract summary from article' };
  return [{ json: { text: `⚠️ ${noContent[language] || noContent.en}`, url, language, charCount, extractMethod, bulletCount: 0, slack_channel, slack_ts, slack_thread_ts } }];
}

// ── Filler-sentence removal ──
const FILLER_STARTS = [
  /^This\s+(strategic|operational|fiscal|historical|massive|directive|depletion|transition|situation|shift|outreach|move|decision|availability|technical|effort|release|step|approach|new\s+generation|latest\s+\w+)\s+\S+/i,
  /^This\s+\w+\s+(aims|seeks|intends|ensures|serves|supports|highlights|mirrors|positions|reflects|demonstrates|underscores|represents|illustrates|facilitates|creates|introduces|marks|signals|offers)\s+/i,
  /^Such\s+(a|an)\s+\S+\s+(would|will|serves|reflects|demonstrates|transforms|ensures)\s+/i,
  /^These\s+\S+\s+(ensure|ensures|serve|serves|support|supports|reflect|reflects)\s+/i,
  /^The\s+(company|article|report)\s+(continues|aims|seeks)\s+/i,
  /^Future\s+developments\s+/i,
  /^(מהלך|צעד|שינוי|מעבר|מצב|החלטה)\s+זה\s+/,
  /^מדובר\s+ב\S*\s+(חשוב|משמעותי|אסטרטגי|היסטורי)/,
  /^בכך\s+\S+\s+(מחזקת|מבטיח|מדגיש)/,
  /^(Это|Данный|Такой)\s+(стратегическое|стратегический|шаг|решение|подход|изменение|переход|сдвиг)\s+/
];

bullets = bullets.map(b => {
  const sentences = b.split(/(?<=[.!?])\s+/);
  const kept = sentences.filter(snt => !FILLER_STARTS.some(rx => rx.test(snt.trim())));
  let cleaned = (kept.length ? kept : sentences).join(' ').replace(/\s+/g, ' ').trim();
  if (cleaned && !/[.!?\u201D"]$/.test(cleaned)) cleaned += '.';
  return cleaned;
}).filter(b => b.length > 25);

if (bullets.length === 0) {
  const noContent = { he: 'לא נותר תוכן לאחר סינון', ru: 'После фильтрации контент не остался', en: 'No content remaining after filtering' };
  return [{ json: { text: `⚠️ ${noContent[language] || noContent.en}`, url, language, charCount, extractMethod, bulletCount: 0, slack_channel, slack_ts, slack_thread_ts } }];
}

bullets = bullets.slice(0, 5);

const RLM = '\u200F';
const LRM = '\u200E';
const wrapLatin = (t) => t.replace(/[A-Za-z0-9]+(?:[.,:\/\-][A-Za-z0-9]+)*/g, (tok) =>
  (/[A-Za-z]/.test(tok) || /[.,:\/\-]/.test(tok)) ? `${LRM}${tok}${LRM}` : tok
);
const esc = (t) => t.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const escLabel = (t) => esc(t).replace(/\|/g, '¦');

const SHOW_MENU = true;
const FOOTER = {
  he: `${RLM}💬 *המשיכו כאן:* שאלו שאלה על הכתבה, או הגיבו באימוג׳י:\n${RLM}🧠 חידון  ·  ⚡ בקצרה  ·  ${language === 'he' ? '🇺🇸 תרגום' : '🇮🇱 עברית'}  ·  📌 שמירה`,
  ru: '💬 *Продолжайте здесь:* задайте вопрос или нажмите реакцию:\n🧠 викторина  ·  ⚡ кратко  ·  🇮🇱 перевод  ·  📌 сохранить',
  en: '💬 *Continue here:* ask a question about the article, or react below:\n🧠 quiz  ·  ⚡ short summary  ·  🇮🇱 Hebrew  ·  📌 save'
};
const footer = SHOW_MENU ? '\n\n' + (FOOTER[language] || FOOTER.en) : '';

let titleLine, bulletLines;
if (language === 'he') {
  const wt = escLabel(wrapLatin(title));
  titleLine = `${RLM}סיכום: ${url ? `<${url}|${wt}>` : wt}`;
  bulletLines = bullets.map(b => `${RLM}• ${esc(wrapLatin(b))}`);
} else if (language === 'ru') {
  const wt = escLabel(title);
  titleLine = url ? `Резюме: <${url}|${wt}>` : `Резюме: ${wt}`;
  bulletLines = bullets.map(b => `• ${esc(b)}`);
} else {
  const wt = escLabel(title);
  titleLine = url ? `Summary: <${url}|${wt}>` : `Summary: ${wt}`;
  bulletLines = bullets.map(b => `• ${esc(b)}`);
}

return [{ json: { text: titleLine + '\n\n' + bulletLines.join('\n\n') + footer, title, url, language, charCount, extractMethod, bulletCount: bullets.length, slack_channel, slack_ts, slack_thread_ts } }];

// ── NEW: Build Wait Notice — typing indicator for all LLM actions ──
const q = $('Prepare Question').first().json;
const lang = q.qLang || 'en';
const mode = q.mode;
const action = q.action || '';
const WAIT = {
  he: { quiz_start:'⏳ מכין חידון…', tldr:'⏳ מסכם בקצרה…', translate:'⏳ מתרגם…', detailed:'⏳ מרחיב…', simple:'⏳ מפשט…', facts:'⏳ מחלץ עובדות…', qa:'⏳ קורא וחושב…' },
  ru: { quiz_start:'⏳ Готовлю викторину…', tldr:'⏳ Сокращаю…', translate:'⏳ Перевожу…', detailed:'⏳ Подробнее…', simple:'⏳ Упрощаю…', facts:'⏳ Извлекаю факты…', qa:'⏳ Думаю…' },
  en: { quiz_start:'⏳ Preparing quiz…', tldr:'⏳ Summarizing…', translate:'⏳ Translating…', detailed:'⏳ Expanding…', simple:'⏳ Simplifying…', facts:'⏳ Extracting facts…', qa:'⏳ Thinking…' }
};
const key = mode === 'rewrite' ? (action || 'qa') : (mode === 'quiz_start' ? 'quiz_start' : 'qa');
const texts = WAIT[lang] || WAIT.en;
const text = texts[key] || texts.qa;
return [{ json: { text, slack_channel: q.slack_channel, slack_thread_ts: q.slack_thread_ts } }];
